#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    vector<vector<int>> graph(n + 1);
    vector<int> to;
    vector<long long> cap, cost;
    for (int i = 0; i < m; i++) {
        int u, v;
        long long c, w;
        scanf("%d %d %lld %lld", &u, &v, &c, &w);
        graph[u].push_back(to.size()); to.push_back(v); cap.push_back(c); cost.push_back(w);
        graph[v].push_back(to.size()); to.push_back(u); cap.push_back(0); cost.push_back(-w);
    }
    int S = 1, T = n;
    long long flow = 0, total = 0;
    const long long INF = LLONG_MAX / 4;
    while (true) {
        vector<long long> dist(n + 1, INF);
        vector<int> pe(n + 1, -1);
        vector<bool> inq(n + 1, false);
        dist[S] = 0;
        deque<int> q = {S};
        while (!q.empty()) {
            int v = q.front(); q.pop_front();
            inq[v] = false;
            for (int e : graph[v])
                if (cap[e] > 0 && dist[v] + cost[e] < dist[to[e]]) {
                    dist[to[e]] = dist[v] + cost[e];
                    pe[to[e]] = e;
                    if (!inq[to[e]]) { inq[to[e]] = true; q.push_back(to[e]); }
                }
        }
        if (dist[T] >= INF) break;
        long long f = INF;
        for (int v = T; v != S; v = to[pe[v] ^ 1]) f = min(f, cap[pe[v]]);
        for (int v = T; v != S; v = to[pe[v] ^ 1]) { cap[pe[v]] -= f; cap[pe[v] ^ 1] += f; }
        flow += f;
        total += f * dist[T];
    }
    printf("%lld %lld\n", flow, total);
    return 0;
}
